// Process incoming PDF binary data
const items = $input.all();
const item = items[0];
const filename = item.json.body?.filename || 'document.pdf';
const base64Data = item.json.body?.file_data;

if (!base64Data) {
  throw new Error('No file data received');
}

return [{
  json: {
    filename: filename,
    received_at: new Date().toISOString(),
    file_size: Math.round(base64Data.length * 0.75) + ' bytes'
  },
  binary: {
    data: {
      data: base64Data,
      mimeType: 'application/pdf',
      fileName: filename
    }
  }
}];

// Parse AI response and structure for Sheets
const aiResponse = $input.first().json;
const extracted = typeof aiResponse.message?.content === 'string' 
  ? JSON.parse(aiResponse.message.content)
  : aiResponse;

return [{
  json: {
    Date: extracted.date || '',
    Vendor: extracted.vendor_name || '',
    Invoice_Number: extracted.invoice_number || '',
    Total_Amount: extracted.total_amount || '0',
    Line_Items: JSON.stringify(extracted.line_items || []),
    Processed_At: new Date().toISOString(),
    Status: 'processed'
  }
}];
